#!/usr/bin/env node

/**
 * Converts command output to mustache template format.
 *
 * This script processes test log files generated by running tests with LOG_TEST_OUTPUT=1.
 * Each log file contains one or more command invocations, and this script generates mustache
 * templates for invocations that have a template path associated with them (via renderRegexFromFile).
 *
 * Usage:
 *   1. Run tests with logging enabled:
 *      LOG_TEST_OUTPUT=1 npm test -- test/commands/config/test-config.js
 *
 *   2. Generate templates from the log files:
 *      node test/helpers/generate-template-from-log.js test/.test-output-logs/<logfile>.log
 */

import fs from 'fs';
import { Chalk } from 'chalk';

function convertToTemplate(stdout, useColor = false) {
	let template = stdout;

	if (useColor) {
		// Create a Chalk instance with colors forced on to generate ANSI codes
		const coloredChalk = new Chalk({ level: 3 });

		// Replace ANSI color codes with mustache color tags for all supported color functions
		for (const fn of [ 'bold', 'blue', 'cyan', 'gray', 'green', 'magenta', 'red', 'yellow', 'underline' ]) {
			// Generate the ANSI codes for this color function by applying it to a placeholder
			const ansiString = coloredChalk[fn]('PLACEHOLDER');

			// Extract the opening and closing ANSI codes
			const openCode = ansiString.substring(0, ansiString.indexOf('PLACEHOLDER'));
			const closeCode = ansiString.substring(ansiString.indexOf('PLACEHOLDER') + 'PLACEHOLDER'.length);

			// Escape the ANSI codes for use in regex
			const openEscaped = openCode.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
			const closeEscaped = closeCode.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

			// Create regex pattern and replacement
			const pattern = new RegExp(`${openEscaped}(.*?)${closeEscaped}`, 'g');

			template = template.replace(pattern, `{{#${fn}}}$1{{/${fn}}}`);
		}
	}

	// Replace version numbers
	template = template.replace(/\b\d+\.\d+\.\d+(-[\w.]+)?\b/g, '{{version}}');

	// Replace year
	template = template.replace(/\b202[0-9]\b/g, '{{year}}');

	// Replace platform-specific strings
	template = template.replace(/darwin-arm64|linux-x64|win32-x64/g, '{{string}}');
	template = template.replace(/node-v\d+\.\d+\.\d+/g, 'node-v{{string}}');

	// Replace time/duration values
	template = template.replace(/\b\d+s\b/g, '{{delta}}');
	template = template.replace(/\b\d+m\s*\d+s\b/g, '{{delta}}');
	template = template.replace(/\b\d+h\s*\d+m\s*\d+s\b/g, '{{delta}}');

	return template;
}

// Get log file path from command line
const logFile = process.argv[2];
if (!logFile) {
	console.error('Usage: node test/helpers/generate-template-from-log.js <test/.test-output-logs/log-file.log>');
	console.error('\nGenerate log files by passing LOG_TEST_OUTPUT=1 when running tests. It\'s recommended to run limited tests with this flag to avoid generating too many logs (e.g. `LOG_TEST_OUTPUT=1 npm test -- test/commands/config/test-config.js`).');
	console.error('\nThis script will process all invocations in the log file and generate templates for those that have a template path specified.');
	process.exit(1);
}

const logData = JSON.parse(fs.readFileSync(logFile, 'utf8'));

// Handle both single invocation (legacy) and array format (new)
const invocations = Array.isArray(logData) ? logData : [logData];

let generated = 0;
let skipped = 0;

for (const invocation of invocations) {
	// Skip if no template path
	if (!invocation.template) {
		skipped++;
		continue;
	}

	// Determine which stream to use based on template filename
	const stream = invocation.template.includes('stderr') ? 'stderr' : 'stdout';
	const useColor = invocation.opts.color === true;
	const template = convertToTemplate(invocation[stream], useColor);

	// Write the template
	fs.writeFileSync(invocation.template, template);
	console.error(`✓ Generated ${invocation.template}`);
	generated++;
}

if (generated === 0 && skipped > 0) {
	console.error(`⚠ No templates generated (${skipped} invocation(s) had no template path)`);
} else if (generated > 0) {
	console.error(`\n✓ Generated ${generated} template(s) (${skipped} skipped)`);
}
